using System.Security.Cryptography;using System.Text;using System.Text.Json;using Microsoft.Extensions.Options;
namespace YoungOne.MediaControl.Agent.Identity;
public sealed class AgentCredentialStore(IOptions<AgentOptions> options){private static readonly byte[]Entropy=Encoding.UTF8.GetBytes("YoungOne.MediaControl.AgentCredential.v1");private readonly string _path=Path.Combine(options.Value.DataDirectory,"credential.dat");public AgentCredential?Load(){if(!File.Exists(_path))return null;byte[]plain=ProtectedData.Unprotect(File.ReadAllBytes(_path),Entropy,DataProtectionScope.LocalMachine);return JsonSerializer.Deserialize<AgentCredential>(plain)??throw new SecurityException("Invalid Agent credential");}public void Save(AgentCredential value){Directory.CreateDirectory(Path.GetDirectoryName(_path)!);byte[]encrypted=ProtectedData.Protect(JsonSerializer.SerializeToUtf8Bytes(value),Entropy,DataProtectionScope.LocalMachine);string temp=_path+".tmp";File.WriteAllBytes(temp,encrypted);File.Move(temp,_path,true);}}
public sealed record AgentCredential(Guid AgentId,string AgentKey);
